void CanvasItem::set_visibility_layer_bit(uint32_t p_visibility_layer, bool p_enable)
{
	ERR_THREAD_GUARD;
	ERR_FAIL_UNSIGNED_INDEX(p_visibility_layer, 32);
	if (p_enable) {
		set_visibility_layer(visibility_layer | (1 << p_visibility_layer));
	}
	else {
		set_visibility_layer(visibility_layer & (~(1 << p_visibility_layer)));
	}
}

