void Viewport::set_canvas_cull_mask_bit(uint32_t p_layer, bool p_enable)
{
	ERR_MAIN_THREAD_GUARD;
	ERR_FAIL_UNSIGNED_INDEX(p_layer, 32);
	if (p_enable) {
		set_canvas_cull_mask(canvas_cull_mask | (1 << p_layer));
	}
	else {
		set_canvas_cull_mask(canvas_cull_mask & (~(1 << p_layer)));
	}
}

