String AudioStreamPlayerInternal::get_bus() const
{
	const String bus_name = bus;
	for (int i = 0; i < AudioServer::get_bus_count(); i++) {
		if (AudioServer::get_bus_name(i) == bus_name) {
			return bus;
		}
	}
	return SceneString(Master);
}

