bool Node3D::_property_can_revert(const String& p_name) const
{
	const String sname = p_name;
	if (sname == "basis") {
		return true;
	}
	else if (sname == "scale") {
		return true;
	}
	else if (sname == "quaternion") {
		return true;
	}
	else if (sname == "rotation") {
		return true;
	}
	else if (sname == "position") {
		return true;
	}
	return false;
}

