bool NavigationAgent3D::_is_target_reachable() const
{
	return target_desired_distance >= _get_final_position().distance_to(target_position);
}

bool NavigationAgent3D::is_navigation_finished()
{
	_update_navigation();
	return navigation_finished;
}

