void GodotShape2D::add_owner(GodotCollisionObject2D* p_owner)
{
	HashMap<GodotCollisionObject2D*, int>::Iterator E = owners.find(p_owner);
	if (E) {
		E->value++;
	}
	else {
		owners[p_owner] = 1;
	}
}

void GodotShape2D::remove_owner(GodotCollisionObject2D* p_owner)
{
	HashMap<GodotCollisionObject2D*, int>::Iterator E = owners.find(p_owner);
	ERR_FAIL_COND(!E);
	E->value--;
	if (E->value == 0) {
		owners.remove(E);
	}
}

